#pragma once

#include <QObject>
#include <QString>
#include <QJsonObject>
#include <QDateTime>
#include <functional>
#include <memory>

namespace redim {

enum class EventType {
    Connected,
    Disconnected,
    AuthSuccess,
    AuthFailed,
    TextMessageReceived,
    ImageMessageReceived,
    MessageSentSuccess,
    MessageSentFailed,
    SessionUpdated,
    PhishingUrlDetected
};

struct EventPacket {
    EventType type;
    qint64 senderId{0};
    qint64 targetId{0};
    QString senderName;
    QString content;
    QString imageUrl;
    QDateTime timestamp;
    QJsonObject rawPayload;
};

/**
 * @brief MessageBus: 全局事件总线与数据中心
 * 利用 Qt 信号槽机制与 C++17 Lambda 表达式实现模块间完全解耦
 */
class MessageBus : public QObject {
    Q_OBJECT

public:
    static MessageBus& instance();

    // 发布通用事件
    void publish(const EventPacket& packet);

    // 辅助快捷事件投递
    void emitTextMessage(qint64 senderId, qint64 targetId, const QString& senderName, 
                         const QString& text, const QDateTime& time);
    void emitImageMessage(qint64 senderId, qint64 targetId, const QString& senderName, 
                          const QString& imageUrl, const QDateTime& time);
    void emitSessionUpdate(qint64 targetId);
    void emitPhishingAlert(const QString& url, const QString& threatType);

signals:
    void eventDispatched(const EventPacket& packet);
    void textMessageArrived(qint64 senderId, qint64 targetId, const QString& name, const QString& text, const QDateTime& time);
    void imageMessageArrived(qint64 senderId, qint64 targetId, const QString& name, const QString& url, const QDateTime& time);
    void connectionStateChanged(bool isConnected);
    void phishingWarningTriggered(const QString& url, const QString& reason);

private:
    explicit MessageBus(QObject* parent = nullptr);
    ~MessageBus() override = default;

    MessageBus(const MessageBus&) = delete;
    MessageBus& operator=(const MessageBus&) = delete;
};

} // namespace redim

#include "redim/core/message_bus.hpp"
#include <QDebug>

namespace redim {

MessageBus& MessageBus::instance() {
    static MessageBus s_bus;
    return s_bus;
}

MessageBus::MessageBus(QObject* parent) : QObject(parent) {
    qInfo() << "[MessageBus] Initialized Global Event Bus & Data Center";
}

void MessageBus::publish(const EventPacket& packet) {
    emit eventDispatched(packet);

    switch (packet.type) {
    case EventType::Connected:
        emit connectionStateChanged(true);
        break;
    case EventType::Disconnected:
        emit connectionStateChanged(false);
        break;
    case EventType::TextMessageReceived:
        emit textMessageArrived(packet.senderId, packet.targetId, packet.senderName, packet.content, packet.timestamp);
        break;
    case EventType::ImageMessageReceived:
        emit imageMessageArrived(packet.senderId, packet.targetId, packet.senderName, packet.imageUrl, packet.timestamp);
        break;
    default:
        break;
    }
}

void MessageBus::emitTextMessage(qint64 senderId, qint64 targetId, const QString& senderName,
                                const QString& text, const QDateTime& time) {
    EventPacket packet;
    packet.type = EventType::TextMessageReceived;
    packet.senderId = senderId;
    packet.targetId = targetId;
    packet.senderName = senderName;
    packet.content = text;
    packet.timestamp = time.isValid() ? time : QDateTime::currentDateTime();
    publish(packet);
}

void MessageBus::emitImageMessage(qint64 senderId, qint64 targetId, const QString& senderName,
                                 const QString& imageUrl, const QDateTime& time) {
    EventPacket packet;
    packet.type = EventType::ImageMessageReceived;
    packet.senderId = senderId;
    packet.targetId = targetId;
    packet.senderName = senderName;
    packet.imageUrl = imageUrl;
    packet.timestamp = time.isValid() ? time : QDateTime::currentDateTime();
    publish(packet);
}

void MessageBus::emitSessionUpdate(qint64 targetId) {
    EventPacket packet;
    packet.type = EventType::SessionUpdated;
    packet.targetId = targetId;
    packet.timestamp = QDateTime::currentDateTime();
    publish(packet);
}

void MessageBus::emitPhishingAlert(const QString& url, const QString& threatType) {
    emit phishingWarningTriggered(url, threatType);
}

} // namespace redim

#pragma once

#include <QObject>
#include <QString>
#include <QNetworkAccessManager>
#include <QNetworkReply>
#include <QWebSocket>
#include <QTimer>
#include <QJsonObject>
#include <QJsonArray>
#include <QJsonDocument>
#include <memory>

namespace redim {

class MiraiClient : public QObject {
    Q_OBJECT

public:
    explicit MiraiClient(const QString& host, quint16 port, const QString& verifyKey, qint64 qqNumber, QObject* parent = nullptr);
    ~MiraiClient() override;

    void startConnection();
    void stopConnection();

    // 消息发送 API
    void sendFriendTextMessage(qint64 friendQq, const QString& message);
    void sendGroupTextMessage(qint64 groupNumber, const QString& message);

    bool isConnected() const { return m_connected; }
    QString sessionKey() const { return m_sessionKey; }

signals:
    void authenticated(const QString& sessionKey);
    void connectionLost(const QString& reason);
    void messageDispatched();

private slots:
    void onWebSocketConnected();
    void onWebSocketDisconnected();
    void onTextMessageReceived(const QString& message);
    void sendHeartbeat();

private:
    void verifyAuth();
    void bindSession();
    void parseIncomingEvent(const QJsonObject& root);
    void parseMessageChain(const QJsonObject& data, qint64 senderId, const QString& senderName, qint64 targetId);

    QString m_host;
    quint16 m_port;
    QString m_verifyKey;
    qint64 m_qqNumber;
    QString m_sessionKey;
    bool m_connected{false};

    QNetworkAccessManager* m_httpManager{nullptr};
    QWebSocket* m_webSocket{nullptr};
    QTimer* m_heartbeatTimer{nullptr};
};

} // namespace redim

#include "redim/network/mirai_client.hpp"
#include "redim/core/message_bus.hpp"
#include <QNetworkRequest>
#include <QUrl>
#include <QDebug>

namespace redim {

MiraiClient::MiraiClient(const QString& host, quint16 port, const QString& verifyKey, qint64 qqNumber, QObject* parent)
    : QObject(parent), m_host(host), m_port(port), m_verifyKey(verifyKey), m_qqNumber(qqNumber) {
    m_httpManager = new QNetworkAccessManager(this);
    m_webSocket = new QWebSocket(QString(), QWebSocketProtocol::VersionLatest, this);
    m_heartbeatTimer = new QTimer(this);

    connect(m_webSocket, &QWebSocket::connected, this, &MiraiClient::onWebSocketConnected);
    connect(m_webSocket, &QWebSocket::disconnected, this, &MiraiClient::onWebSocketDisconnected);
    connect(m_webSocket, &QWebSocket::textMessageReceived, this, &MiraiClient::onTextMessageReceived);
    connect(m_heartbeatTimer, &QTimer::timeout, this, &MiraiClient::sendHeartbeat);
}

MiraiClient::~MiraiClient() {
    stopConnection();
}

void MiraiClient::startConnection() {
    qInfo() << "[MiraiClient] Initiating connection to mirai-api-http at" << m_host << ":" << m_port;
    verifyAuth();
}

void MiraiClient::stopConnection() {
    m_heartbeatTimer->stop();
    if (m_webSocket->isValid()) {
        m_webSocket->close();
    }
    m_connected = false;
    MessageBus::instance().publish({EventType::Disconnected, 0, 0, "", "Connection terminated", "", QDateTime::currentDateTime(), {}});
}

void MiraiClient::verifyAuth() {
    QUrl url(QString("http://%1:%2/verify").arg(m_host).arg(m_port));
    QNetworkRequest request(url);
    request.setHeader(QNetworkRequest::ContentTypeHeader, "application/json");

    QJsonObject body;
    body["verifyKey"] = m_verifyKey;

    QNetworkReply* reply = m_httpManager->post(request, QJsonDocument(body).toJson());
    connect(reply, &QNetworkReply::finished, [this, reply]() {
        reply->deleteLater();
        if (reply->error() != QNetworkReply::NoError) {
            qWarning() << "[MiraiClient] Auth verify failed:" << reply->errorString();
            emit connectionLost(reply->errorString());
            return;
        }

        QJsonObject res = QJsonDocument::fromJson(reply->readAll()).object();
        if (res.value("code").toInt() == 0) {
            m_sessionKey = res.value("session").toString();
            qInfo() << "[MiraiClient] Acquired Session Key:" << m_sessionKey;
            bindSession();
        } else {
            qWarning() << "[MiraiClient] Auth rejected by server, code:" << res.value("code").toInt();
        }
    });
}

void MiraiClient::bindSession() {
    QUrl url(QString("http://%1:%2/bind").arg(m_host).arg(m_port));
    QNetworkRequest request(url);
    request.setHeader(QNetworkRequest::ContentTypeHeader, "application/json");

    QJsonObject body;
    body["sessionKey"] = m_sessionKey;
    body["qq"] = m_qqNumber;

    QNetworkReply* reply = m_httpManager->post(request, QJsonDocument(body).toJson());
    connect(reply, &QNetworkReply::finished, [this, reply]() {
        reply->deleteLater();
        if (reply->error() != QNetworkReply::NoError) {
            qWarning() << "[MiraiClient] Bind session failed:" << reply->errorString();
            return;
        }

        QJsonObject res = QJsonDocument::fromJson(reply->readAll()).object();
        if (res.value("code").toInt() == 0) {
            qInfo() << "[MiraiClient] Session bound successfully for QQ:" << m_qqNumber;
            // 打开 WebSocket 实时消息推送信道
            QUrl wsUrl(QString("ws://%1:%2/message?sessionKey=%3").arg(m_host).arg(m_port).arg(m_sessionKey));
            m_webSocket->open(wsUrl);
            m_heartbeatTimer->start(15000); // 15秒心跳
        }
    });
}

void MiraiClient::onWebSocketConnected() {
    m_connected = true;
    qInfo() << "[MiraiClient] WebSocket message push channel connected!";
    MessageBus::instance().publish({EventType::Connected, m_qqNumber, 0, "Self", "Online", "", QDateTime::currentDateTime(), {}});
    emit authenticated(m_sessionKey);
}

void MiraiClient::onWebSocketDisconnected() {
    m_connected = false;
    qWarning() << "[MiraiClient] WebSocket disconnected, scheduled reconnect in 5s";
    m_heartbeatTimer->stop();
    MessageBus::instance().publish({EventType::Disconnected, 0, 0, "", "WebSocket link broken", "", QDateTime::currentDateTime(), {}});
    QTimer::singleShot(5000, this, &MiraiClient::startConnection);
}

void MiraiClient::onTextMessageReceived(const QString& message) {
    QJsonDocument doc = QJsonDocument::fromJson(message.toUtf8());
    if (!doc.isObject()) return;
    parseIncomingEvent(doc.object());
}

void MiraiClient::parseIncomingEvent(const QJsonObject& root) {
    QString type = root.value("type").toString();
    QJsonObject data = root.value("data").toObject();

    if (type == "FriendMessage") {
        QJsonObject sender = data.value("sender").toObject();
        qint64 senderId = sender.value("id").toVariant().toLongLong();
        QString senderName = sender.value("nickname").toString();
        parseMessageChain(data, senderId, senderName, senderId);
    } else if (type == "GroupMessage") {
        QJsonObject sender = data.value("sender").toObject();
        QJsonObject group = sender.value("group").toObject();
        qint64 senderId = sender.value("id").toVariant().toLongLong();
        qint64 groupId = group.value("id").toVariant().toLongLong();
        QString senderName = sender.value("memberName").toString();
        parseMessageChain(data, senderId, senderName, groupId);
    }
}

void MiraiClient::parseMessageChain(const QJsonObject& data, qint64 senderId, const QString& senderName, qint64 targetId) {
    QJsonArray chain = data.value("messageChain").toArray();
    QDateTime timestamp = QDateTime::fromSecsSinceEpoch(data.value("time").toVariant().toLongLong());

    for (const auto& elemVal : chain) {
        QJsonObject elem = elemVal.toObject();
        QString elemType = elem.value("type").toString();

        if (elemType == "Plain") {
            QString text = elem.value("text").toString();
            MessageBus::instance().emitTextMessage(senderId, targetId, senderName, text, timestamp);
        } else if (elemType == "Image") {
            QString imageUrl = elem.value("url").toString();
            MessageBus::instance().emitImageMessage(senderId, targetId, senderName, imageUrl, timestamp);
        }
    }
}

void MiraiClient::sendHeartbeat() {
    if (!m_connected || m_sessionKey.isEmpty()) return;
    QUrl url(QString("http://%1:%2/about").arg(m_host).arg(m_port));
    QNetworkRequest req(url);
    QNetworkReply* reply = m_httpManager->get(req);
    connect(reply, &QNetworkReply::finished, [reply]() {
        reply->deleteLater();
    });
}

void MiraiClient::sendFriendTextMessage(qint64 friendQq, const QString& message) {
    QUrl url(QString("http://%1:%2/sendFriendMessage").arg(m_host).arg(m_port));
    QNetworkRequest request(url);
    request.setHeader(QNetworkRequest::ContentTypeHeader, "application/json");

    QJsonObject body;
    body["sessionKey"] = m_sessionKey;
    body["target"] = friendQq;

    QJsonArray chain;
    QJsonObject plainElem;
    plainElem["type"] = "Plain";
    plainElem["text"] = message;
    chain.append(plainElem);
    body["messageChain"] = chain;

    QNetworkReply* reply = m_httpManager->post(request, QJsonDocument(body).toJson());
    connect(reply, &QNetworkReply::finished, [this, reply, friendQq, message]() {
        reply->deleteLater();
        if (reply->error() == QNetworkReply::NoError) {
            MessageBus::instance().emitTextMessage(m_qqNumber, friendQq, "我", message, QDateTime::currentDateTime());
        }
    });
}

void MiraiClient::sendGroupTextMessage(qint64 groupNumber, const QString& message) {
    QUrl url(QString("http://%1:%2/sendGroupMessage").arg(m_host).arg(m_port));
    QNetworkRequest request(url);
    request.setHeader(QNetworkRequest::ContentTypeHeader, "application/json");

    QJsonObject body;
    body["sessionKey"] = m_sessionKey;
    body["target"] = groupNumber;

    QJsonArray chain;
    QJsonObject plainElem;
    plainElem["type"] = "Plain";
    plainElem["text"] = message;
    chain.append(plainElem);
    body["messageChain"] = chain;

    QNetworkReply* reply = m_httpManager->post(request, QJsonDocument(body).toJson());
    connect(reply, &QNetworkReply::finished, [this, reply, groupNumber, message]() {
        reply->deleteLater();
        if (reply->error() == QNetworkReply::NoError) {
            MessageBus::instance().emitTextMessage(m_qqNumber, groupNumber, "我", message, QDateTime::currentDateTime());
        }
    });
}

} // namespace redim

#pragma once

#include <QString>
#include <QDateTime>
#include <QList>
#include <QMap>
#include <algorithm>

namespace redim {

enum class MessageType {
    Text,
    Image,
    Notice,
    System
};

struct ChatMessage {
    qint64 msgId{0};
    qint64 senderId{0};
    QString senderName;
    QString content;
    QString imageUrl;
    MessageType type{MessageType::Text};
    QDateTime timestamp;
    bool isOutgoing{false};
};

struct SessionItem {
    qint64 targetId{0};
    QString title;
    QString lastMessagePreview;
    QDateTime lastMessageTime;
    int unreadCount{0};
    bool isPinned{false};
    bool isGroup{false};
};

/**
 * @brief CustomListSort: 重写 List 的会话多级排序算法
 * 克服的困难：高频刷新下保持置顶会话优先、未读权重计算与精确时间戳倒序
 */
class CustomListSort {
public:
    static void sortSessions(QList<SessionItem>& list) {
        std::sort(list.begin(), list.end(), [](const SessionItem& a, const SessionItem& b) {
            // 1. 置顶会话优先级最高
            if (a.isPinned != b.isPinned) {
                return a.isPinned > b.isPinned;
            }
            // 2. 具备未读消息的会话优先上浮
            bool aHasUnread = (a.unreadCount > 0);
            bool bHasUnread = (b.unreadCount > 0);
            if (aHasUnread != bHasUnread) {
                return aHasUnread > bHasUnread;
            }
            // 3. 按照最后一条消息的最新毫秒时间戳倒序排列
            return a.lastMessageTime > b.lastMessageTime;
        });
    }
};

/**
 * @brief ChatSessionManager: 数据中心会话缓存与消息历史管理
 */
class ChatSessionManager {
public:
    static ChatSessionManager& instance();

    void addMessage(qint64 targetId, const ChatMessage& msg, bool isGroup = false);
    QList<ChatMessage> getMessages(qint64 targetId) const;
    QList<SessionItem> getSortedSessions();
    void markRead(qint64 targetId);
    void setPinned(qint64 targetId, bool pinned);

private:
    ChatSessionManager() = default;
    QMap<qint64, QList<ChatMessage>> m_historyStore;
    QMap<qint64, SessionItem> m_sessionMap;
};

} // namespace redim

#include "redim/models/chat_session.hpp"

namespace redim {

ChatSessionManager& ChatSessionManager::instance() {
    static ChatSessionManager s_mgr;
    return s_mgr;
}

void ChatSessionManager::addMessage(qint64 targetId, const ChatMessage& msg, bool isGroup) {
    m_historyStore[targetId].append(msg);

    // 更新或新增会话元信息
    SessionItem& item = m_sessionMap[targetId];
    item.targetId = targetId;
    item.isGroup = isGroup;
    if (item.title.isEmpty()) {
        item.title = isGroup ? QString("群聊 (%1)").arg(targetId) : msg.senderName;
    }

    if (msg.type == MessageType::Image) {
        item.lastMessagePreview = "[图片]";
    } else {
        item.lastMessagePreview = msg.content;
    }
    item.lastMessageTime = msg.timestamp;

    if (!msg.isOutgoing) {
        item.unreadCount++;
    }
}

QList<ChatMessage> ChatSessionManager::getMessages(qint64 targetId) const {
    return m_historyStore.value(targetId);
}

QList<SessionItem> ChatSessionManager::getSortedSessions() {
    QList<SessionItem> list = m_sessionMap.values();
    // 调用重写的 List 排序算法
    CustomListSort::sortSessions(list);
    return list;
}

void ChatSessionManager::markRead(qint64 targetId) {
    if (m_sessionMap.contains(targetId)) {
        m_sessionMap[targetId].unreadCount = 0;
    }
}

void ChatSessionManager::setPinned(qint64 targetId, bool pinned) {
    if (m_sessionMap.contains(targetId)) {
        m_sessionMap[targetId].isPinned = pinned;
    }
}

} // namespace redim

