MainWindow::MainWindow(QWidget* parent) : QMainWindow(parent) {
    setupUi();
    applyCustomStyles();

    // 绑定全局消息总线信号（利用 Qt 信号槽与 C++ Lambda）
    connect(&MessageBus::instance(), &MessageBus::textMessageArrived,
            this, &MainWindow::handleIncomingTextMessage);
    connect(&MessageBus::instance(), &MessageBus::imageMessageArrived,
            this, &MainWindow::handleIncomingImageMessage);
    connect(&MessageBus::instance(), &MessageBus::connectionStateChanged,
            this, [this](bool connected) {
                m_statusBadge->setText(connected ? "● 在线 (Project-Mirai 已连接)" : "○ 离线 / 重连中");
                m_statusBadge->setStyleSheet(connected ? "color: #10B981; font-weight: bold;" : "color: #EF4444; font-weight: bold;");
            });

    connect(&MessageBus::instance(), &MessageBus::phishingWarningTriggered,
            this, [](const QString& url, const QString& reason) {
                QMessageBox::warning(nullptr, "安全中心拦截提醒", QString("检测到危险钓鱼链接：
%1

原因：%2").arg(url, reason));
            });
}

void MainWindow::setupUi() {
    setWindowTitle("RedIM v2.2.4 - 跨平台即时通信客户端 (童亦洲)");
    resize(960, 680);

    auto* centralWidget = new QWidget(this);
