void MainWindow::refreshSessionList() {
    m_sessionList->clear();
    auto sessions = ChatSessionManager::instance().getSortedSessions();
    for (const auto& item : sessions) {
        QString text = QString("%1
%2")
                           .arg(item.title)
                           .arg(item.lastMessagePreview.isEmpty() ? "暂无消息" : item.lastMessagePreview);
        if (item.unreadCount > 0) {
            text += QString("  [%1 未读]").arg(item.unreadCount);
        }
        m_sessionList->addItem(text);
    }
}

void MainWindow::onSessionSelected(int index) {
    auto sessions = ChatSessionManager::instance().getSortedSessions();
    if (index < 0 || index >= sessions.size()) return;

    m_currentActiveTarget = sessions[index].targetId;
    m_chatTitleLabel->setText(sessions[index].title);
    ChatSessionManager::instance().markRead(m_currentActiveTarget);

    m_chatHistoryView->clear();
    auto msgs = ChatSessionManager::instance().getMessages(m_currentActiveTarget);
    for (const auto& m : msgs) {
        appendChatMessageHtml(m);
    }
}

void MainWindow::onSendMessageClicked() {
    QString text = m_inputEdit->toPlainText().trimmed();
    if (text.isEmpty() || m_currentActiveTarget == 0) return;

    ChatMessage msg;
    msg.senderId = 10001;
    msg.senderName = "我";
    msg.content = text;
    msg.type = MessageType::Text;
    msg.timestamp = QDateTime::currentDateTime();
    msg.isOutgoing = true;

    ChatSessionManager::instance().addMessage(m_currentActiveTarget, msg);
    appendChatMessageHtml(msg);
    m_inputEdit->clear();
    refreshSessionList();
}

void MainWindow::onSelectImageClicked() {
    QString path = QFileDialog::getOpenFileName(this, "选择要发送的图片", "", "Images (*.png *.jpg *.jpeg *.gif)");
    if (path.isEmpty() || m_currentActiveTarget == 0) return;

    ChatMessage msg;
    msg.senderId = 10001;
    msg.senderName = "我";
    msg.imageUrl = path;
    msg.type = MessageType::Image;
    msg.timestamp = QDateTime::currentDateTime();
    msg.isOutgoing = true;

    ChatSessionManager::instance().addMessage(m_currentActiveTarget, msg);
    appendChatMessageHtml(msg);
    refreshSessionList();
}

void MainWindow::appendChatMessageHtml(const ChatMessage& msg) {
    QString timeStr = msg.timestamp.toString("HH:mm:ss");
    QString align = msg.isOutgoing ? "right" : "left";
    QString bgColor = msg.isOutgoing ? "#2563EB" : "#334155";
    QString name = msg.senderName;

    QString contentHtml;
    if (msg.type == MessageType::Image) {
        contentHtml = QString("<img src='%1' width='240' style='border-radius:6px;'/>").arg(msg.imageUrl);
    } else {
        contentHtml = AntiPhishing::sanitizeTextWithWarnings(msg.content.toHtmlEscaped());
    }

    QString html = QString(
        "<div style='text-align:%1; margin: 8px 0;'>"
        "  <span style='font-size:11px; color:#94A3B8;'>%2 (%3)</span><br/>"
        "  <div style='display:inline-block; background-color:%4; color:#FFFFFF; padding:8px 12px; border-radius:10px; margin-top:3px; max-width:70%;'>"
        "    %5"
        "  </div>"
        "</div>"
    ).arg(align, name, timeStr, bgColor, contentHtml);

    m_chatHistoryView->append(html);
}

void MainWindow::handleIncomingTextMessage(qint64 senderId, qint64 targetId, const QString& name, const QString& text, const QDateTime& time) {
    ChatMessage msg;
    msg.senderId = senderId;
    msg.senderName = name;
    msg.content = text;
    msg.type = MessageType::Text;
    msg.timestamp = time;
    msg.isOutgoing = false;

    ChatSessionManager::instance().addMessage(targetId, msg);
    if (targetId == m_currentActiveTarget) {
        appendChatMessageHtml(msg);
    }
    refreshSessionList();
}

void MainWindow::handleIncomingImageMessage(qint64 senderId, qint64 targetId, const QString& name, const QString& url, const QDateTime& time) {
    ChatMessage msg;
    msg.senderId = senderId;
    msg.senderName = name;
    msg.imageUrl = url;
    msg.type = MessageType::Image;
    msg.timestamp = time;
    msg.isOutgoing = false;

    ChatSessionManager::instance().addMessage(targetId, msg);
    if (targetId == m_currentActiveTarget) {
        appendChatMessageHtml(msg);
    }
    refreshSessionList();
}

